/* ── L3 hotfix (M4) ─────────────────────────────────────────────── */

/* Payload location. /data is tmpfs on this board: the payload is pushed
 * per-session by the operator (fwpush) and does not survive reboot;
 * Flash persistence is a post-defense roadmap item (SmartFS). */
#define HOTFIX_ELF_PATH AGENT_DATA_DIR "/patches/buggy_app_fixed"
/* Refuse absurd payloads early; the real one is ~5 KB. */
#define HOTFIX_MAX_BYTES (16 * 1024)

/* SiliconLoop: exec_spawn() is NuttX binfmt's caller-provided-symbol-table
 * loader that starts a NEW task and returns (binfmt.h: exec_spawn).
 * posix_spawn() is not an option here: CONFIG_EXECFUNCS_HAVE_SYMTAB is
 * off, so the OS-side symbol table posix_spawn relies on does not exist
 * and the relocatable ELF could not be linked. exec() (the image-swap
 * variant used by the elf example) would replace the agent's own image. */
#ifndef SILILOOP_HOST_TEST
#include <nuttx/binfmt/binfmt.h>
#endif

static int stop_task(void)
{
    pid_t pid;
    if (read_pid(&pid) == OK) {
        kill(pid, SIGTERM);
        for (int i = 0; i < 20; i++) {
            if (kill(pid, 0) != 0) {
                break;
            }
            usleep(100000);
        }
    }
    return OK;
}

/* ── audit + verdict ────────────────────────────────────────────── */

static void audit(const char *target, const char *action,
    long pre, long post, const char *result)
{
    FILE *f = fopen(ACTIONS_LOG, "a");
    if (f) {
        fprintf(f, "%ld,%s,%s,pre=%ld,post=%ld,%s\n",
            (long)time(NULL), target, action, pre, post, result);
        fclose(f);
    }
}

static void flag_needs_human(void)
{
    FILE *f = fopen(NEEDS_HUMAN, "w");
    if (f) {
        fprintf(f, "l3 failed\n");
        fclose(f);
    }
}

/* Payload sanity before handing the file to the loader: exists, regular,
 * size within [sizeof(Elf32_Ehdr), HOTFIX_MAX_BYTES]. A truncated or
 * hostile file must fail HERE, not inside load_module. */
#ifndef SILILOOP_HOST_TEST
static int hotfix_payload_ok(const char *path)
{
    struct stat st;
    if (stat(path, &st) != 0 || !S_ISREG(st.st_mode)) {
        syslog(LOG_WARNING, "[%s] hotfix payload missing: %s\n", TAG, path);
        return ERROR;
    }
    if (st.st_size < 52 || st.st_size > HOTFIX_MAX_BYTES) {
        syslog(LOG_WARNING, "[%s] hotfix payload size invalid: %ld\n",
            TAG, (long)st.st_size);
        return ERROR;
    }
    return OK;
}
#endif /* !SILILOOP_HOST_TEST */

/* L3: stop the faulty task, exec the fixed ELF as a NEW task (exec_spawn
 * keeps the agent alive and returns the new pid), and let the fixed
 * build re-publish its identity files. On spawn failure the payload is
 * left in place (operator may re-push it) and the ladder escalates.
 * Host tests have no NuttX exec_spawn (and glibc's spawnattr has no
 * priority field): compiled out there; L3 coverage is board acceptance. */
#ifndef SILILOOP_HOST_TEST
static int rung_hotfix(const char *mode, long *post_delta)
{
    pid_t pid;
    char *argv[3];
    posix_spawnattr_t attr;

    if (hotfix_payload_ok(HOTFIX_ELF_PATH) != OK) {
        return ERROR;
    }

    stop_task();

    /* Same priority/stack as the buggy build's registration (hello_app
     * Makefile: PRIORITY 50, STACKSIZE 4096) so the fixed task behaves
     * like the one it replaces. exec_module reads priority/stacksize
     * directly off the attr (binfmt_exec.c), no flags needed. */
    posix_spawnattr_init(&attr);
    attr.priority = 50;
    attr.stacksize = 4096;

    argv[0] = (char *)"buggy_app_fixed";
    if (mode && strcmp(mode, "normal") != 0) {
        argv[1] = (char *)mode;
        argv[2] = NULL;
    } else {
        argv[1] = NULL;
    }

    pid = exec_spawn(HOTFIX_ELF_PATH, argv, NULL,
        g_hotfix_exports, g_hotfix_nexports, NULL, &attr);
    posix_spawnattr_destroy(&attr);
    if (pid < 0) {
        syslog(LOG_ERR, "[%s] exec_spawn(%s) failed: %d\n",
            TAG, HOTFIX_ELF_PATH, errno);
        return ERROR;
    }
    syslog(LOG_INFO, "[%s] hotfix task started pid=%d\n", TAG, (int)pid);

    usleep(6000000);
    return measure_delta(post_delta);
}
#endif /* !SILILOOP_HOST_TEST */

/* ── one rung ───────────────────────────────────────────────────── */

/* Returns OK when the rung executed (post_delta set), ERROR when it
 * could not run at all (e.g. no pid file for L1). */
static int rung(int level, const char *target, long *post_delta)
{
    char mode[32];
    (void)target; /* L1/L2 act on the pid/mode files; L3 has one payload */
    read_mode(mode, sizeof(mode));

    switch (level) {
    case 0: { /* L1 resume */
        pid_t pid;
        if (read_pid(&pid) != OK) {
            return ERROR;
        }
        if (kill(pid, SIGUSR1) != 0) {
            return ERROR;
        }
        usleep(3000000);
        return measure_delta(post_delta);
    }
    case 1: /* L2 restart, same workload */
        stop_task();
        if (respawn(RUN_ELF_PATH, mode) != 0) {
            return ERROR;
        }
        usleep(6000000);
        return measure_delta(post_delta);
    case 2: /* L3 hotfix: exec the fixed ELF from /data/patches (M4) */
#ifndef SILILOOP_HOST_TEST
        return rung_hotfix(mode, post_delta);
#else
        return ERROR; /* no exec_spawn on host; ladder exhausts */
#endif
    default:
        return ERROR;
    }
}
