static int stop_task(void)
{
    pid_t pid;
    if (read_pid(&pid) == OK) {
        kill(pid, SIGTERM);
        for (int i = 0; i < 20; i++) {
            if (kill(pid, 0) != 0) {
                break;
            }
            usleep(100000);
        }
    }
    return OK;
}

